"""Legacy-compatible numeric division for the modern platform."""

from __future__ import annotations


def _legacy_number(value: object) -> float:
    """Coerce a value using the legacy numeric rules."""
    if value is None:
        return 0.0

    if isinstance(value, str):
        if value.strip() == "":
            return 0.0

    try:
        return float(value)
    except Exception:
        # Values outside the supported numeric domain are treated as empty
        # in the same defensive numeric context.
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using legacy CRMScript division-by-zero semantics."""
    try:
        numerator = _legacy_number(a)
        denominator = _legacy_number(b)

        if denominator == 0.0:
            return 0.0, ["SCRIPT_DIV0"]

        return numerator / denominator, []
    except Exception:
        # The legacy evaluator never propagates division errors.
        return 0.0, ["SCRIPT_DIV0"]
